SELECT "id", "title", "body", "level", "analysis", "lemma_counts", "source", "license", "ord" FROM jsonb_populate_recordset(NULL::ling."library_text", '[{"id":"lib-001","ord":1,"body":"Volám sa Peter a bývam v Bratislave. Dnes je pekný deň. Ráno idem do práce. Na ulici vidím veľa ľudí. Pracujem v novom obchode na námestí. V práci mám dobrý počítač. Po práci idem s kamarátom do kina alebo do múzea. Môj brat býva v malom meste pri Bratislave. Má dom, ženu a päť detí. Často mu pomáham. Dnes mu kúpim novú knihu a dobrú kávu. Večer som doma a čítam slovenskú knihu. A kde bývaš ty?","level":"A2","title":"Môj deň","source":"authored","license":"CC BY 4.0","analysis":{"v":1,"lemmas":{"2":{"pos":"noun","gloss":["friend"],"lemma":"kamarát","gender":"m_anim"},"3":{"pos":"noun","gloss":["brother"],"lemma":"brat","gender":"m_anim"},"6":{"pos":"noun","gloss":["house","home"],"lemma":"dom","gender":"m_inan"},"7":{"pos":"noun","gloss":["shop, store","trade, business"],"lemma":"obchod","gender":"m_inan"},"9":{"pos":"noun","gloss":["computer"],"lemma":"počítač","gender":"m_inan"},"11":{"pos":"noun","gloss":["woman","wife"],"lemma":"žena","gender":"f"},"12":{"pos":"noun","gloss":["book"],"lemma":"kniha","gender":"f"},"13":{"pos":"noun","gloss":["coffee"],"lemma":"káva","gender":"f"},"14":{"pos":"noun","gloss":["street"],"lemma":"ulica","gender":"f"},"15":{"pos":"noun","gloss":["work, job"],"lemma":"práca","gender":"f"},"20":{"pos":"noun","gloss":["town, city"],"lemma":"mesto","gender":"n"},"21":{"pos":"noun","gloss":["cinema"],"lemma":"kino","gender":"n"},"24":{"pos":"noun","gloss":["square (in a town)"],"lemma":"námestie","gender":"n"},"26":{"pos":"noun","gloss":["museum"],"lemma":"múzeum","gender":"n"},"28":{"pos":"noun","gloss":["people"],"lemma":"ľudia","gender":"m_anim"},"30":{"pos":"noun","gloss":["day"],"lemma":"deň","gender":"m_inan"},"31":{"pos":"noun","gloss":["Bratislava (capital of Slovakia)"],"lemma":"Bratislava","gender":"f"},"32":{"pos":"adj","gloss":["nice, pretty, beautiful"],"lemma":"pekný"},"33":{"pos":"adj","gloss":["new"],"lemma":"nový"},"34":{"pos":"adj","gloss":["good"],"lemma":"dobrý"},"36":{"pos":"adj","gloss":["Slovak"],"lemma":"slovenský"},"38":{"pos":"pron","gloss":["you (one person, informal)"],"lemma":"ty"},"39":{"pos":"pron","gloss":["he","it (masculine noun)"],"lemma":"on"},"41":{"pos":"pron","gloss":["my, mine"],"lemma":"môj"},"45":{"pos":"prep","gloss":["to, into (+ genitive)","until"],"lemma":"do"},"50":{"pos":"prep","gloss":["in, at (+ locative)","on (a day, + accusative)"],"lemma":"v"},"51":{"pos":"prep","gloss":["on, at (+ locative)","onto, to (+ accusative)"],"lemma":"na"},"53":{"pos":"prep","gloss":["by, near (+ locative)"],"lemma":"pri"},"54":{"pos":"prep","gloss":["after, along (+ locative)"],"lemma":"po"},"55":{"pos":"prep","gloss":["with (+ instrumental)"],"lemma":"s"},"59":{"pos":"num","gloss":["five"],"lemma":"päť"},"60":{"pos":"verb","gloss":["to be"],"lemma":"byť"},"61":{"pos":"verb","gloss":["to have"],"lemma":"mať"},"62":{"pos":"verb","gloss":["to go (on foot)"],"lemma":"ísť"},"63":{"pos":"verb","gloss":["to see"],"lemma":"vidieť"},"64":{"pos":"verb","gloss":["to live (somewhere), to reside"],"lemma":"bývať"},"65":{"pos":"verb","gloss":["to help"],"lemma":"pomáhať"},"66":{"pos":"verb","gloss":["to work"],"lemma":"pracovať"},"67":{"pos":"verb","gloss":["to buy"],"lemma":"kúpiť"},"68":{"pos":"conj","gloss":["and"],"lemma":"a"},"71":{"pos":"adv","gloss":["today"],"lemma":"dnes"},"72":{"pos":"adv","gloss":["where"],"lemma":"kde"}},"sentences":[{"e":36,"s":0,"en":"My name is Peter and I live in Bratislava.","tokens":[{"e":5,"s":0,"t":"word"},{"e":8,"s":6,"t":"word"},{"e":14,"s":9,"t":"word"},{"e":16,"l":68,"m":"single","s":15,"t":"word"},{"e":22,"l":64,"m":"single","s":17,"t":"word","tag":"v:Kesa+"},{"e":24,"l":50,"m":"single","s":23,"t":"word"},{"e":35,"l":31,"m":"rule","s":25,"t":"word","tag":"s6","trig":{"i":5,"id":"prep-v-loc","kind":"preposition"}},{"e":36,"s":35,"t":"punct"}]},{"e":55,"s":37,"en